#!/usr/bin/env python3
import argparse
import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime

def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO‑8601 timestamp possibly containing a UTC offset.
    datetime.fromisoformat handles offsets in Python 3.7+.
    """
    try:
        return datetime.fromisoformat(ts)
    except ValueError:
        # Fallback: replace space with T and try again
        ts_fixed = ts.replace(' ', 'T')
        return datetime.fromisoformat(ts_fixed)

def main():
    parser = argparse.ArgumentParser(description='Reconcile payment transactions')
    parser.add_argument('--input', required=True, help='Path to transactions CSV file')
    args = parser.parse_args()

    # Mapping tx_id -> (timestamp, amount, status)
    records = {}

    try:
        with open(args.input, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                tx_id = row.get('tx_id')
                ts_raw = row.get('timestamp')
                amount_raw = row.get('amount')
                status = row.get('status')
                if not (tx_id and ts_raw and amount_raw and status):
                    # Skip malformed rows
                    continue
                try:
                    ts = parse_timestamp(ts_raw)
                except Exception:
                    # Skip rows with unparsable timestamps
                    continue
                try:
                    amount = Decimal(amount_raw)
                except Exception:
                    # Skip rows with invalid amount
                    continue
                # Keep the latest timestamp for each tx_id
                if tx_id in records:
                    if ts > records[tx_id][0]:
                        records[tx_id] = (ts, amount, status)
                else:
                    records[tx_id] = (ts, amount, status)
    except FileNotFoundError:
        sys.stderr.write(f"Error: file '{args.input}' not found\n")
        sys.exit(1)
    except Exception as e:
        sys.stderr.write(f"Error reading CSV: {e}\n")
        sys.exit(1)

    total_valid = Decimal('0')
    valid_count = 0
    failed_count = 0

    for ts, amount, status in records.values():
        if status == 'VALID':
            total_valid += amount
            valid_count += 1
        else:
            failed_count += 1

    # Round to two decimal places using ROUND_HALF_UP
    total_valid = total_valid.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    result = {
        "total_valid_amount": float(total_valid),
        "valid_count": valid_count,
        "failed_count": failed_count
    }
    json.dump(result, sys.stdout)
    sys.stdout.write('\n')

if __name__ == '__main__':
    main()
